import test from 'node:test';
import assert from 'node:assert/strict';
import { readFile, readdir, stat } from 'node:fs/promises';
import { join } from 'node:path';

/**
 * Brand artwork contract.
 *
 * The SVGs are the source of truth; the rasters are generated by tools/render-brand.mjs. These
 * tests keep the vectors self-contained (no remote references, fonts come from the vendored folder),
 * keep them accessible (role/title/desc), and prove the exported rasters exist at the sizes the
 * platform slots expect.
 */

const ROOT = new URL('../../', import.meta.url).pathname;
const BRAND = join(ROOT, 'assets/brand');
const DIST = join(ROOT, 'dist/brand');

const EXPECTED_RASTERS = [
  ['snake-poster-1200x630.png', 1200, 630],
  ['snake-poster-2400x1260.png', 2400, 1260],
  ['og-card-1200x630.jpg', 1200, 630],
  ['og-card-1600x840.jpg', 1600, 840],
  ['logo-512x512.png', 512, 512],
  ['logo-96x96.png', 96, 96],
  ['favicon-32x32.png', 32, 32],
  ['favicon-180x180.png', 180, 180],
  ['favicon-192x192.png', 192, 192],
  ['favicon-512x512.png', 512, 512],
];

const pngSize = (buffer) => {
  assert.equal(buffer.subarray(1, 4).toString('ascii'), 'PNG', 'not a PNG');
  return { width: buffer.readUInt32BE(16), height: buffer.readUInt32BE(20) };
};

const jpegSize = (buffer) => {
  assert.equal(buffer[0], 0xff, 'not a JPEG');
  assert.equal(buffer[1], 0xd8, 'not a JPEG');
  let offset = 2;
  while (offset < buffer.length) {
    if (buffer[offset] !== 0xff) {
      offset += 1;
      continue;
    }
    const marker = buffer[offset + 1];
    const size = buffer.readUInt16BE(offset + 2);
    if (marker >= 0xc0 && marker <= 0xcf && ![0xc4, 0xc8, 0xcc].includes(marker)) {
      return { height: buffer.readUInt16BE(offset + 5), width: buffer.readUInt16BE(offset + 7) };
    }
    offset += 2 + size;
  }
  throw new Error('no start-of-frame marker found');
};

test('brand: the vector sources are self-contained and accessible', async () => {
  const files = (await readdir(BRAND)).filter((name) => name.endsWith('.svg'));
  assert.deepEqual(
    files.sort(),
    ['favicon.svg', 'logo.svg', 'og-card.svg', 'snake-poster.svg'],
    'unexpected brand source list',
  );
  for (const name of files) {
    const svg = await readFile(join(BRAND, name), 'utf8');
    assert.match(svg, /<title[^>]*>[^<]+<\/title>/, `${name} needs a title`);
    assert.match(svg, /<desc[^>]*>[^<]+<\/desc>/, `${name} needs a description`);
    assert.match(svg, /role="img"/, `${name} must be exposed as an image`);
    assert.match(svg, /aria-labelledby/, `${name} must point assistive tech at its title and description`);
    assert.doesNotMatch(svg, /xlink:href|<image/, `${name} must not embed rasters`);
    assert.doesNotMatch(svg, /(href|src)="https?:|@import|url\((['"]?)http/, `${name} must not reach the network`);
    if (/<text/.test(svg)) {
      assert.match(svg, /font-family="'?(Space Grotesk|Silkscreen)/, `${name} should set its text in the vendored faces`);
      assert.match(svg, /@font-face/, `${name} declares its faces inline — a fallback render must still be on-brand`);
    }
  }
});

test('brand: poster and share card are one canvas with one accent set', async () => {
  const poster = await readFile(join(BRAND, 'snake-poster.svg'), 'utf8');
  const card = await readFile(join(BRAND, 'og-card.svg'), 'utf8');
  assert.match(poster, /viewBox="0 0 1200 630"/);
  assert.match(card, /viewBox="0 0 1200 630"/, 'the share card must be the same 1.91:1 canvas');
  const accents = ['#3FD07A', '#8FF9B8', '#FF6B57', '#157F47', '#060B08'];
  const upper = (svg) => svg.toUpperCase();
  for (const hex of accents) {
    assert.ok(upper(poster).includes(hex), `the poster dropped ${hex}`);
    assert.ok(upper(card).includes(hex), `the share card dropped ${hex}`);
  }
});

test('brand: the share card embeds the logo mark rather than redrawing it', async () => {
  const cells = (svg) => [...svg.matchAll(/<rect x="([\d.]+)" y="([\d.]+)" width="7" height="7" rx="2\.3"\/>/g)].map((m) => `${m[1]},${m[2]}`);
  const logo = cells(await readFile(join(BRAND, 'logo.svg'), 'utf8'));
  const card = cells(await readFile(join(BRAND, 'og-card.svg'), 'utf8'));
  assert.ok(logo.length >= 5, 'the logo mark should be five body cells');
  assert.deepEqual(card, logo, 'the card must reuse the logo geometry verbatim, scaled');
  const favicon = await readFile(join(BRAND, 'favicon.svg'), 'utf8');
  const faviconCells = (favicon.match(/<rect x=/g) ?? []).length;
  assert.ok(faviconCells >= 3 && faviconCells <= logo.length, 'the favicon is the same mark, thinned for 32px');
  assert.match(favicon, /#3FD07A[\s\S]*#FF6B57/, 'the favicon keeps the same two accents');
});

test('brand: raster exports exist at the platform sizes and match their headers', async () => {
  const present = new Set(await readdir(DIST).catch(() => []));
  for (const [name, width, height] of EXPECTED_RASTERS) {
    assert.ok(present.has(name), `${name} missing — run: node tools/render-brand.mjs`);
    const buffer = await readFile(join(DIST, name));
    const size = name.endsWith('.png') ? pngSize(buffer) : jpegSize(buffer);
    assert.deepEqual(size, { width, height }, `${name} is ${size.width}x${size.height}`);
    // a blank render still compresses, so this only catches truncation; the size check above does the work
    const floor = width <= 64 ? 300 : 2000;
    assert.ok(buffer.length > floor, `${name} is suspiciously small`);
  }
});

test('brand: no raster art is checked into the source tree', async () => {
  const offenders = [];
  const walk = async (dir) => {
    for (const entry of await readdir(dir, { withFileTypes: true })) {
      const path = join(dir, entry.name);
      if (entry.isDirectory()) {
        if (['node_modules', 'dist', '.build', '.cache', '.git'].includes(entry.name)) continue;
        await walk(path);
      } else if (/\.(png|jpg|jpeg|gif|webp|avif|bmp)$/i.test(entry.name)) {
        offenders.push(path);
      }
    }
  };
  await walk(ROOT);
  assert.deepEqual(offenders, [], 'all source art must be SVG; rasters belong in dist/brand');
});

test('brand: the page wires the logo, favicon and share image', async () => {
  const html = await readFile(join(ROOT, 'index.html'), 'utf8');
  assert.match(html, /rel="icon"[\s\S]*favicon\.svg/);
  assert.match(html, /property="og:image" content="dist\/brand\/og-card-1200x630\.jpg"/);
  assert.match(html, /name="twitter:image" content="dist\/brand\/og-card-1200x630\.jpg"/);
  assert.match(html, /property="og:image:alt"/, 'a share image needs alt text');
  assert.match(html, /name="twitter:card" content="summary_large_image"/);
  assert.match(html, /class="brand-mark"[\s\S]{0,160}width="40" height="40"/, 'the header mark should reserve its box to avoid layout shift');
  const info = await stat(join(BRAND, 'logo.svg'));
  assert.ok(info.size < 12_000, 'the inline logo should stay small');
});
